        height: 40px;
    }
    table {
        width: 100%;
        border-collapse: collapse;
        margin-bottom: 20px;
    }
    thead {
        display: table-header-group;
    }
    th, td {
        border: 1px solid #ddd;
        padding: 6px;
        text-align: left;
    }
    th {
        background-color: #f2f2f2;
    }
    td {
        font-size: 10px;
    }
    tr:nth-child(even) {
        background-color: #f9f9f9;
    }
    .footer {
        font-size: 10px;
        text-align: right;
        padding: 5px 10px;
        border-top: 1px solid #ccc;
    }
    .col-protocolo {
        width: 130px;
        word-break: break-word;
    }
    .col-criado {
        width: 100px;
        word-break: break-word;
    }
</style>

<div class='header'>
    <div class='title'>Relatório de Inspeção de Pátio</div>
</div>

<table>
    <thead>
        <tr>
            <th class='col-protocolo'>Protocolo</th>
            <th>Criado em</th>
            <th>Local</th>
            <th>Item</th>
            <th>Status</th>
            <th>Descrição</th>
        </tr>
    </thead>
    <tbody>" &

Concat(
        If(
            !IsBlank(var_consultaItensInspecao),
            Filter(
                tbl_inspPatioItens,
                ID_insp = var_consultaItensInspecao.ID
            ),
            FirstN(
                Sort(
                    Filter(
                        tbl_inspPatioItens,
                        (IsBlank(cmbHomeAeroporto_5.Selected.Result) || StartsWith(
                            Aeroporto,
                            Text(cmbHomeAeroporto_5.Selected.Result)
                        )) && 
                        (IsBlank(cmbHomeBloco_5.Selected.Value) || StartsWith(
                            Bloco,
                            Text(cmbHomeBloco_5.Selected.Value)
                        )) && 
                        (IsBlank(cmbApontStatus_1.Selected.Value) || StartsWith(
                            Status,
                            cmbApontStatus_1.Selected.Value
                        )) && 
                        (IsBlank(cmbHomeLocal_1.Selected.Value) || StartsWith(
                            Local,
                            cmbHomeLocal_1.Selected.Value
                        )) && 
                        (IsBlank(cmbHomeItem_2.Selected.Value) || StartsWith(
                            Item,
                            cmbHomeItem_2.Selected.Value
                        )) && 
                        Criado >= dtpHomeDtfInicio_5.SelectedDate && 
                        Criado <= If(
                            IsBlank(dtpHomeDtfTermino_5.SelectedDate),
                            Today(),
                            DateAdd(dtpHomeDtfTermino_5.SelectedDate, 1, TimeUnit.Days)
                        )
                    ),
                    ID,
                    SortOrder.Descending
                ),
                Value(txtLimitApont_1.Text)
            )
        ),
    "<tr><td class='col-protocolo'>" & LookUp(colAeros, Aeroporto = cmbHomeAeroporto_5.Selected.Result).IATA & "-INSP-PÁTIO-" & ID & "</td>" &
    "<td class='col-criado'>" & Text(Criado, "[$-pt-BR]dd/mm/yyyy HH:mm") & "</td>" &
    "<td>" & Local & "</td>" &
    "<td>" & Item & "</td>" &
    "<td>" & Status & "</td>" &
    "<td>" & Descricao & "</td></tr>"
) &

"</tbody></table>
<div class='footer'>Gerado em: " & Text(Now(), "[$-pt-BR]dd/mm/yyyy HH:mm") & "</div>"

